"""The human-review disclaimer, one wording shared by the API, reports, CSV and the console."""

DISCLAIMER_TITLE = "AI-generated analysis: human review required"
DISCLAIMER_TEXT = (
    "This output was generated by AI and can be wrong. "
    "A qualified human analyst must review it before any action is taken."
)
# Markdown line appended to the orchestrator report. Bold so it survives being pasted elsewhere.
DISCLAIMER_MARKDOWN = f"**{DISCLAIMER_TITLE}.** {DISCLAIMER_TEXT}"


def with_disclaimer_markdown(report_markdown: str) -> str:
    """Return the report opening and ending with the bold disclaimer line.

    Each end is checked on its own, so a report that already has one end gets only the other
    and calling this twice never duplicates either.
    """
    body = report_markdown.strip()
    if not body:
        return DISCLAIMER_MARKDOWN
    if not body.startswith(DISCLAIMER_MARKDOWN):
        body = f"{DISCLAIMER_MARKDOWN}\n\n---\n\n{body}"
    if not body.endswith(DISCLAIMER_MARKDOWN):
        body = f"{body}\n\n---\n\n{DISCLAIMER_MARKDOWN}"
    return body
